module dma_controller (
    input wire clk,
    input wire reset,
    input wire start,
    input wire [31:0] src_addr,
    input wire [31:0] dest_addr,
    input wire [15:0] transfer_size,
    output reg busy,
    output reg [31:0] mem_read_data,
    output reg [31:0] mem_write_data
);

    reg [31:0] current_src_addr;
    reg [31:0] current_dest_addr;
    reg [15:0] bytes_remaining;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            busy <= 0;
            current_src_addr <= 32'b0;
            current_dest_addr <= 32'b0;
            bytes_remaining <= 16'b0;
            mem_read_data <= 32'b0;
            mem_write_data <= 32'b0;
        end else if (start && !busy) begin
            busy <= 1;
            current_src_addr <= src_addr;
            current_dest_addr <= dest_addr;
            bytes_remaining <= transfer_size;
        end else if (busy) begin
            if (bytes_remaining > 0) begin
                mem_read_data <= current_src_addr; // Simulating read from memory
                mem_write_data <= mem_read_data; // Simulating write to memory
                current_src_addr <= current_src_addr + 4; // Assuming 32-bit data
                current_dest_addr <= current_dest_addr + 4;
                bytes_remaining <= bytes_remaining - 1;
            end else begin
                busy <= 0; // Transfer complete
            end
        end
    end
endmodule

