    input start,  
    output reg [7:0] ciphertext,  
    output reg done  
);  

reg [7:0] state;  
reg [2:0] round;  

// S-box for substitution  
function [7:0] sbox;  
    input [7:0] data;  
    begin  
        case (data)  
            8'h00: sbox = 8'h63;  
            8'h01: sbox = 8'h7c;  
            8'h02: sbox = 8'h77;  
            8'h03: sbox = 8'h7b;  
            // ... Fill in the rest of the S-box values  
            8'hff: sbox = 8'h16;  
            default: sbox = data;  
        endcase  
    end  
endfunction  

always @(posedge clk) begin  
    if (start) begin  
        state <= plaintext;  
        round <= 0;  
        done <= 0;  
    end else if (round < 2) begin  
        state <= sbox(state ^ key);  
        round <= round + 1;  
    end else if (round == 2) begin  
        ciphertext <= state;  
        done <= 1;  
    end  
end  

endmodule

