module pcie_endpoint_controller (  
    input wire clk,  
    input wire reset,  
    input wire [1:0] req_type,  
    output reg ack  
);  

    reg [2:0] state;  
    reg [2:0] next_state;  
    parameter IDLE = 3'b000, READ = 3'b001, WRITE = 3'b010;  

    always @(posedge clk or posedge reset) begin  
        if (reset)  
            state <= IDLE;  
        else  
            state <= next_state;  
    end  

    always @(*) begin  
        case (state)  
            IDLE: begin  
                if (req_type == 2'b01) // Read request  
                    next_state = READ;  
                else if (req_type == 2'b10) // Write request  
                    next_state = WRITE;  
                else  
                    next_state = IDLE;  
            end  
            READ: begin  
                next_state = IDLE;  
            end  
            WRITE: begin  
                next_state = IDLE;  
            end  
            default: next_state = IDLE;  
        endcase  
    end  

    always @(posedge clk) begin  
        ack <= (state == READ || state == WRITE);  
    end  
endmodule

