module reset_controller (
    input wire clk,
    input wire reset_n,
    output reg reset_out
);
    parameter RESET_DELAY = 10; // Number of clock cycles for reset to be asserted
    reg [3:0] counter;

    always @(posedge clk or negedge reset_n) begin
        if (!reset_n) begin
            counter <= 0;
            reset_out <= 0;
        end else if (counter < RESET_DELAY) begin
            counter <= counter + 1;
            reset_out <= 0;
        end else begin
            reset_out <= 1;
        end
    end
endmodule

