module fractional_n_pll (
    input wire clk_in,
    input wire [7:0] integer_part,
    input wire [7:0] fractional_part,
    output reg clk_out
);

    reg [15:0] counter;
    reg [7:0] fractional_counter;

    always @(posedge clk_in) begin
        if (counter < integer_part) begin
            clk_out <= 1'b1;
        end else if (counter < (integer_part + fractional_part)) begin
            clk_out <= 1'b0;
        end else begin
            clk_out <= 1'b1;
            counter <= 0; // Reset counter after reaching the full cycle
        end
        counter <= counter + 1;
    end

    initial begin
        counter = 0;
        clk_out = 0;
    end

endmodule

