module chebyshev_filter (  
    input clk,  
    input rst,  
    input [7:0] x_in,  
    output reg [7:0] y_out  
);  
    reg [7:0] x [0:4];  // 5 delay elements for 4th order filter  
    reg [7:0] y [0:4];  // Output signals for the filter stages  
    integer i;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            for (i = 0; i < 5; i = i + 1) begin  
                x[i] <= 8'b0;  
                y[i] <= 8'b0;  
            end  
            y_out <= 8'b0;  
        end else begin  
            // Shift inputs  
            x[0] <= x_in;  
            for (i = 1; i < 5; i = i + 1) begin  
                x[i] <= x[i-1];  
            end  
            // Chebyshev filter coefficients (example values)  
            y[0] <= (x[0] + 2*x[1] + x[2]) >> 1;  
            y[1] <= (y[0] + x[3]) >> 1;  
            y[2] <= (y[1] + x[4]) >> 1;  
            y[3] <= (y[2] + y[1]) >> 1;  

            y_out <= y[3];  
        end  
    end  
endmodule

