module I2C_Master (
    input clk,
    input rst,
    input start,
    input [7:0] data_in,
    output reg scl,
    output reg sda,
    output reg busy
);
    reg [3:0] state;
    reg [3:0] bit_cnt;

    localparam IDLE = 4'd0;
    localparam START = 4'd1;
    localparam SEND_BIT = 4'd2;
    localparam STOP = 4'd3;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            scl <= 1;
            sda <= 1;
            busy <= 0;
            bit_cnt <= 4'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (start) begin
                        busy <= 1;
                        state <= START;
                    end
                end
                START: begin
                    sda <= 0; // Start condition
                    state <= SEND_BIT;
                end
                SEND_BIT: begin
                    if (bit_cnt < 8) begin
                        scl <= 0; // Pull SCL low
                        sda <= data_in[7 - bit_cnt]; // Send bit
                        bit_cnt <= bit_cnt + 1;
                        state <= SEND_BIT;
                    end else begin
                        // After sending 8 bits, go to stop
                        state <= STOP;
                    end
                end
                STOP: begin
                    scl <= 0;
                    sda <= 0; // Prepare for stop condition
                    scl <= 1; // Release SCL
                    sda <= 1; // Release SDA
                    busy <= 0;
                    state <= IDLE;
                    bit_cnt <= 0; // Reset bit counter
                end
            endcase
        end
    end
endmodule

