module butterworth_filter (
    input wire clk,
    input wire rst,
    input wire signed [7:0] x_in,  // 8-bit signed input
    output reg signed [11:0] y_out  // 12-bit signed output
);

    // Filter coefficients for 2nd order Butterworth (example values)
    parameter signed [11:0] b0 = 12'h1E;    // Coefficient for current input
    parameter signed [11:0] b1 = 12'h1E;    // Coefficient for previous input
    parameter signed [11:0] b2 = 12'h1E;    // Coefficient for input two samples ago
    parameter signed [11:0] a1 = 12'h2D;    // Coefficient for output one sample ago
    parameter signed [11:0] a2 = 12'h1D;    // Coefficient for output two samples ago

    reg signed [11:0] x_delay1, x_delay2;  // Delayed input values
    reg signed [11:0] y_delay1, y_delay2;  // Delayed output values

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            y_out <= 12'd0;
            x_delay1 <= 12'd0;
            x_delay2 <= 12'd0;
            y_delay1 <= 12'd0;
            y_delay2 <= 12'd0;
        end else begin
            // Update delays
            x_delay2 <= x_delay1;
            x_delay1 <= {{4{x_in[7]}}, x_in}; // Sign extend to 12 bits
            y_delay2 <= y_delay1;
            // Calculate current output
            y_out <= (b0 * x_delay1 + b1 * x_delay2 - a1 * y_delay1 - a2 * y_delay2) >>> 4; 
        end
    end

endmodule

