module ARQ_System (
    input [4:0] data_in,
    input ack,
    input clk,
    input reset,
    output reg [4:0] data_out,
    output reg tx_ready
);
    reg [4:0] last_sent_data;
    reg state; // 0: waiting for ack, 1: sending data

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            tx_ready <= 1;
            data_out <= 5'b00000;
            last_sent_data <= 5'b00000;
            state <= 0;
        end else begin
            if (tx_ready) begin
                data_out <= data_in;
                last_sent_data <= data_in;
                tx_ready <= 0;
                state <= 1; // now in sending state
            end else if (state == 1) begin
                if (ack) begin
                    tx_ready <= 1; // ready to send new data
                    state <= 0; // back to waiting state
                end else begin
                    data_out <= last_sent_data; // retransmit last data
                end
            end
        end
    end
endmodule

