module instruction_pipeline (
    input clk,
    input reset,
    input [31:0] instruction_in,
    output reg [31:0] result_out,
    output reg data_ready
);
    reg [31:0] IF_reg, ID_reg, EX_reg, WB_reg;
    reg [1:0] state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            IF_reg <= 32'b0;
            ID_reg <= 32'b0;
            EX_reg <= 32'b0;
            WB_reg <= 32'b0;
            data_ready <= 0;
            state <= 0;
        end else begin
            case (state)
                0: begin // IF stage
                    IF_reg <= instruction_in;
                    state <= 1;
                end
                1: begin // ID stage
                    ID_reg <= IF_reg;
                    state <= 2;
                end
                2: begin // EX stage
                    EX_reg <= ID_reg; // For simplicity, let's assume EX just forwards the instruction
                    state <= 3;
                end
                3: begin // WB stage
                    WB_reg <= EX_reg;
                    result_out <= WB_reg;
                    data_ready <= 1;
                    state <= 0; // Reset to IF stage
                end
            endcase
        end
    end
endmodule

