module fractional_n_pll (  
    input wire clk_ref,  
    input wire reset,  
    input wire [3:0] division_ratio,  
    input wire [3:0] fractional_multiplier,  
    output reg clk_out  
);  
    reg [7:0] counter;  
    wire clk_div;  

    assign clk_div = (counter < division_ratio) ? 1'b1 : 1'b0;  

    always @(posedge clk_ref or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            clk_out <= 0;  
        end else begin  
            if (counter < (division_ratio + fractional_multiplier)) begin  
                counter <= counter + 1;  
            end else begin  
                counter <= 0;  
                clk_out <= ~clk_out;  
            end  
        end  
    end  
endmodule

