module serializer_16bit (  
    input clk,  
    input reset,  
    input [15:0] data_in,  
    output reg serialized_out  
);  
    reg [3:0] bit_counter;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            serialized_out <= 0;  
            bit_counter <= 0;  
        end else begin  
            if (bit_counter < 16) begin  
                serialized_out <= data_in[15 - bit_counter];  
                bit_counter <= bit_counter + 1;  
            end else begin  
                serialized_out <= 0;  
            end  
        end  
    end  
endmodule

