module reset_controller (
    input wire clk,
    input wire rst_in,
    output reg rst_out
);

parameter DEBOUNCE_TIME = 4'd10; // 10 clock cycles
reg [3:0] debounce_counter;
reg rst_in_sync;

// Synchronize reset input
always @(posedge clk) begin
    rst_in_sync <= rst_in;
end

// Debounce logic
always @(posedge clk) begin
    if (rst_in_sync) begin
        debounce_counter <= 0;
        rst_out <= 1'b0; // Assert reset
    end else if (debounce_counter < DEBOUNCE_TIME) begin
        debounce_counter <= debounce_counter + 1;
        rst_out <= 1'b0; // Keep reset asserted
    end else begin
        rst_out <= 1'b1; // Deassert reset
    end
end

endmodule

