module deserializer (
    input wire clk,
    input wire rst,
    input wire [31:0] data_in,
    output reg [7:0] data_out,
    output reg valid
);
    reg [1:0] state;
    reg [2:0] count;

    // State encoding
    localparam IDLE = 2'b00, OUTPUT = 2'b01;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            state <= IDLE;
            count <= 3'b000;
            data_out <= 8'b0;
            valid <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (count < 4) begin
                        state <= OUTPUT;
                    end
                end
                OUTPUT: begin
                    data_out <= data_in[8*count +: 8]; // Select 8 bits from the input
                    valid <= 1;
                    count <= count + 1;
                    if (count == 3) begin
                        state <= IDLE;
                        count <= 0;
                    end
                end
            endcase
        end
    end
endmodule

