module pll (
    input wire clk_in,          // Input clock
    input wire reset,          // Active high reset
    output reg clk_out         // Output clock
);
    reg [1:0] div_count;
    reg vco;                   // Voltage Controlled Oscillator output
    reg phase_error;          // Phase error signal

    // Frequency divider
    always @(posedge clk_in or posedge reset) begin
        if (reset) begin
            div_count <= 2'b00;
            vco <= 0;
        end else begin
            div_count <= div_count + 1;
            if (div_count == 2'b11) begin
                vco <= ~vco; // Toggle VCO output every 4 input clocks
            end
        end
    end

    // Phase detector and control (simple toggle based on phase error)
    always @(posedge vco or posedge reset) begin
        if (reset) begin
            clk_out <= 0;
            phase_error <= 0;
        end else begin
            phase_error <= clk_in ^ vco; // Calculate phase error
            if (phase_error) begin
                clk_out <= ~clk_out; // Toggle output clock on phase error
            end
        end
    end
endmodule

