module uart_controller (
    input clk,
    input rst,
    input start_transmit,
    input [7:0] data_in,
    output reg tx,
    output reg busy
);
    parameter BAUD_RATE_DIV = 104; // Example for 9600 baud with 100 MHz clock
    reg [6:0] baud_counter;
    reg [3:0] bit_counter;
    reg [1:0] state;

    localparam IDLE = 2'b00,
               TRANSMIT = 2'b01,
               STOP = 2'b10;

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            tx <= 1;
            busy <= 0;
            baud_counter <= 0;
            bit_counter <= 0;
            state <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    busy <= 0;
                    if (start_transmit) begin
                        tx <= 0; // Start bit
                        busy <= 1;
                        bit_counter <= 0;
                        state <= TRANSMIT;
                    end
                end
                TRANSMIT: begin
                    if (baud_counter == BAUD_RATE_DIV - 1) begin
                        baud_counter <= 0;
                        if (bit_counter < 8) begin
                            tx <= data_in[bit_counter];
                            bit_counter <= bit_counter + 1;
                        end else begin
                            tx <= 1; // Stop bit
                            state <= STOP;
                        end
                    end else begin
                        baud_counter <= baud_counter + 1;
                    end
                end
                STOP: begin
                    if (baud_counter == BAUD_RATE_DIV - 1) begin
                        tx <= 1; // Idle state
                        busy <= 0;
                        state <= IDLE;
                    end else begin
                        baud_counter <= baud_counter + 1;
                    end
                end
            endcase
        end
    end
endmodule

