module watchdog_timer(  
    input wire clk,  
    input wire kick,  
    output reg reset  
);  
    parameter TIMEOUT = 8'd100; // Timeout period in clock cycles  
    reg [7:0] counter;  

    always @(posedge clk) begin  
        if (kick) begin  
            counter <= 0;  
            reset <= 0;  
        end else begin  
            if (counter < TIMEOUT) begin  
                counter <= counter + 1;  
                reset <= 0;  
            end else begin  
                reset <= 1;  
            end  
        end  
    end  
endmodule

