module PID_Controller (
    input wire clk,
    input wire reset,
    input wire [15:0] setpoint,
    input wire [15:0] feedback,
    output reg [15:0] control_signal
);
    reg [15:0] prev_error;
    reg [15:0] integral;
    reg [15:0] proportional;
    reg [15:0] derivative;
    reg [15:0] error;

    parameter [15:0] Kp = 16'd1;  // Proportional gain
    parameter [15:0] Ki = 16'd1;  // Integral gain
    parameter [15:0] Kd = 16'd1;  // Derivative gain

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            control_signal <= 16'd0;
            prev_error <= 16'd0;
            integral <= 16'd0;
        end else begin
            error <= setpoint - feedback;
            proportional <= Kp * error;
            integral <= integral + (Ki * error);
            derivative <= Kd * (error - prev_error);
            control_signal <= proportional + integral + derivative;
            prev_error <= error;
        end
    end
endmodule

