module rsa_encryptor(  
    input clk,  
    input rst,  
    input [15:0] plaintext,  
    input [15:0] exponent,  
    output reg [15:0] ciphertext  
);  
    reg [15:0] result;  
    reg [15:0] base;  
    reg [15:0] exp;  
    reg [4:0] count;  
    parameter MODULUS = 65537;  
    parameter DELAY = 5;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            result <= 16'b1;  
            base <= plaintext;  
            exp <= exponent;  
            count <= 5'b0;  
            ciphertext <= 16'b0;  
        end else if (count < DELAY) begin  
            count <= count + 1;  
        end else if (count == DELAY) begin  
            if (exp > 0) begin  
                if (exp[0])  
                    result <= (result * base) % MODULUS;  
                base <= (base * base) % MODULUS;  
                exp <= exp >> 1;  
            end else begin  
                ciphertext <= result;  
            end  
        end  
    end  
endmodule

